/**
 * 섹션 1 · 유닛 4 — 어디에 있어요?
 * 출처: 서울대 한국어 1A 4과
 *
 * 배우는 것
 *   장소        공항·우체국·대사관·은행·가게·약국·병원·미용실
 *               백화점·극장·식당·학교·회사·도서관·시장·서점·빵집·화장실
 *   위치        위·아래[밑]·앞·뒤·옆·안
 *   지시        여기·거기·저기·어디
 *   문법        여기가 N이에요/예요  ·  N에 있어요[없어요]
 *               N에 가요[와요]      ·  N 앞[뒤, 옆]에 있어요
 *
 * 유닛 4 규칙 (유닛 2와 같다)
 *   - 타이핑 계열은 아직 안 넣는다. 유닛 5부터.
 *   - 빈칸은 전부 단일 빈칸. 다중 빈칸은 섹션 2부터.
 *   - word_matching / audio_match 는 짧은 단어만, 5쌍 고정.
 *   - speaking 은 한 사람이 말하는 짧은 문장만.
 *   - 같은 타입을 연달아 두지 않는다.
 *   - reply_builder 는 대화를 다루는 레슨에만 하나씩.
 *
 * 이 유닛에서 처음 나오는 조사 "에"
 *   받침을 따지지 않는다. 늘 "에" 하나다. 대신 "에서"와 헷갈리기 쉬워서
 *   (있는 곳 / 가는 곳 → 에, 무엇을 하는 곳 → 에서) 노드 5에서 따로 대비시킨다.
 */

